"""A common evidence-led reading path for the six GOSR ranking sections."""
from html import escape as E
from goso_reading import Tree, Node, fragment

PATH=['核心问题','指标定位','核心发现','交互证据','行动建议']
TOPICS={
1:dict(code='R',name='全球行政区划影响力排行榜',short='地区',role='协作在哪里聚集',question='哪些地区已成为开源协作的重要节点，参与规模与影响力怎样共同呈现？',metric='以 OpenRank 观察地区在协作网络中的位置，以开发者规模补充参与基础。全球行政区、中国省级行政区与中国城市分别排名，保持同一层级比较。',window='2025.07—2026.06 · OpenRank / 开发者数量（万）',findings=[('规模与影响力，呈现不同排序','英格兰位列影响力第 2，开发者 487.08 万；卡纳塔克邦位列第 8，开发者 570.53 万。参与规模更大，未必对应更靠前的网络位置。',1),('100 个节点，分布在 32 个国家','美国入榜行政区 25 个、印度 12 个、中国 7 个。这是入榜节点数量，反映榜单的地理结构。',2),('中国城市呈现多个重要节点','北京、上海居前，杭州、深圳分列第 3、第 4。把城市放回省级视角，可以同时查看区域位置和具体节点。',3)],guide='先比较地区影响力与参与规模，再看国家入榜分布，最后通过省市联动定位具体节点。',figures=['地区榜：比较规模与网络位置','国家分布：识别入榜节点的集中程度','省市联动：在同一图里定位中国节点'],hints=['切换全球、省级与城市榜；搜索和指标排序保留原榜次。','默认展示前十名及并列国家，点击国家可联动主榜。','点击省份，查看省级名次及关联城市的全国位次。'],actions=[('按同层级选择对标对象','地方与高校可先选参与规模相近的地区，再结合网络位置识别需要深入研究的协作差异。','从主榜切换地区层级与指标',1),('把人才支持连接到具体项目','补充本地开发者参与的项目、维护角色和跨地区协作记录，让培养计划对应持续贡献的机会。','从省市节点继续追踪项目与维护者',3),('围绕共同项目连接城市','以共同维护的基础软件为入口，组织高校、企业与社区跨城市共建，并持续记录协作成果。','从节点清单形成后续共建调研范围',3)],bridge='地区提供协作发生的空间。接下来，观察持续投入其中的企业。'),
2:dict(code='C',name='全球开源企业影响力排行榜',short='企业',role='谁在持续投入',question='哪些企业形成了重要的开源影响，它们的参与结构与位置正在怎样变化？',metric='OpenRank 是本期榜单主序，关联活跃仓库和开发者补充参与规模。年度与月度名次分别观察长期位置和近期变化。',window='2025.07—2026.06 · 本期榜 / 所选企业历史记录',findings=[('榜单前二，有不同的参与结构','微软、华为的 OpenRank 分别为 167,060.26 和 141,253.65。微软关联开发者更多，华为关联活跃仓库更多。',1),('总榜领先与近期换位同时存在','微软位居本期全球总榜首位；2026 年 3—6 月月度记录中，华为连续位列第 1，微软第 2。',2),('中国企业也出现阶段性换位','本期中国榜中阿里巴巴第 2、字节跳动第 3；2026 年 4—6 月月度记录中，两者顺序交换。',2)],guide='从企业主榜查参与结构，把关注对象带入历史位次；共同贡献案例补充下一步合作观察方式。',figures=['企业榜：影响力与参与结构','位次变化：长期位置与近期信号','共同贡献：从共享项目发现协作入口'],hints=['点击企业查看档案；可切换规模视角或选择三家对照。','年度和月度分别阅读，最多比较十家企业的实线轨迹。','本图为虚构演示：企业、项目和贡献数均为模拟，用于评审观察方式。'],actions=[('让开源投入对应维护责任','企业可结合榜单与参与结构，明确长期维护的项目、责任团队和对外协作接口。','从企业档案与关联规模开始',1),('在同一组对象上持续跟踪','同时保留总榜和月度记录；出现换位时，再核查相关项目、贡献来源及统计范围的变化。','在位次图选定长期关注名单',2),('围绕共享项目寻找共建机会','补齐真实企业贡献映射后，可识别共同维护的项目和互补力量，再讨论合作方式与共同投入。','以共同贡献图作为后续数据清单',3)],bridge='企业持续投入之外，基金会为跨组织共建提供另一种组织形态。'),
3:dict(code='F',name='全球开源基金会影响力排行榜',short='基金会',role='谁在组织共建',question='哪些基金会汇聚了重要的开源协作，如何理解它们的组织层级与持续位置？',metric='基金会以 OpenRank 排序，关联开发者和代表项目说明组织范围。Linux 基金会整体与旗下组织分别展示，各自保留统计层级。',window='2025.07—2026.06 · 21 家原榜主体 / 8 家月度记录',findings=[('Linux 家族居首，开放原子与 Apache 随后','前三者 OpenRank 分别为 196,128.27、99,965.35 和 81,247.51。Linux 条目按原表包含子基金会。',1),('头部成员稳定，第二、第三位仍有交换','12 个月记录中，Linux 家族始终居首；2025 年 10 月和 2026 年 1 月，Apache 位于开放原子之前，其余月份顺序相反。',3)],guide='先比较全球基金会，再沿代表项目理解组织边界；旗下组织榜展示分层观察方式，全球月度记录提供真实历史参照。',figures=['全球基金会榜：组织位置与代表项目','Linux 基金会旗下组织：展开第二级榜单','位次变化：在同一组织层级观察历史'],hints=['代表项目是理解组织范围的入口，可打开官方介绍。','组织与项目名称来自官方资料；旗下组织榜次、分值和人数暂为模拟。','全球基金会轨迹为原始数据；切换旗下组织后，轨迹为明确标记的模拟。'],actions=[('从代表项目核查维护需求','资助方可沿基金会的代表项目识别关键公共基础软件，再核查维护负担、人员梯队和支持缺口。','从基金会榜打开项目官方入口',1),('公开组织与项目的有效边界','基金会持续维护旗下组织、项目和仓库映射，记录生效时间，使整体与子组织的比较可以复核。','沿两级榜单整理归并清单',2),('把治理证据接到影响力之后','持续补充维护者梯队、跨组织参与和治理透明度，让支持决策同时看到协作影响与维护条件。','将代表项目与历史记录作为跟踪起点',3)],bridge='组织连接协作者，项目承载共同成果。下一节进入具体项目。'),
4:dict(code='P',name='全球开源项目影响力排行榜',short='项目',role='哪些共同成果形成影响',question='哪些项目处于开源协作网络前列，它们的技术方向与贡献力量如何展开？',metric='项目按标签聚合一个或多个仓库，以 OpenRank 排序。技术领域、原表组织标签与开发者规模补充背景；贡献来源采用独立证据。',window='2025.07—2026.06 · 全球原表 Top 30 / Top 100 国家汇总',findings=[('OpenHarmony 位居原榜首位','OpenRank 为 75,809.42，约为第二名 Azure（29,382.06）的 2.58 倍。项目边界和覆盖仓库共同构成理解数值的背景。',1),('AI 基础软件进入头部协作网络','PyTorch 第 4、vLLM 第 7、CANN 第 13，与操作系统、编译器和开发工具共同进入原表前列。',1),('组织归属揭示另一层结构','真实 Top 100 国家汇总中，美国标签 69 个、中国标签 7 个、未识别 9 个。该表描述原表组织归属，贡献者所在地另行观察。',2)],guide='先从项目榜定位对象和领域，再看真实国家汇总；贡献来源图展示待补数据的观察方案。',figures=['项目榜：在技术领域中寻找具体对象','榜单结构：国家分布、领域与两期位置','贡献来源：展开国家、组织和仓库群体'],hints=['全球前 30 名来自原表；第 31—100 位的名次与指标为模拟补位，并逐项标明。','国家分布使用独立真实 Top 100 汇总，领域分布默认原表 Top 30。','榜次与项目名称为真实前十，贡献数量及份额为模拟，当前不据此判断真实主导国。'],actions=[('建立分领域的重点项目清单','公共部门、企业与研究团队可筛选与产业研发和公共基础设施相关的项目，再核查持续维护需求。','使用主榜领域筛选缩小调研范围',1),('沿项目边界追踪维护责任','项目团队补齐仓库清单、组件分工和维护职责，把影响力榜次连接到可持续的共同成果。','结合项目档案明确统计与维护边界',1),('以贡献证据识别合作力量','在真实国家、组织和仓库贡献数据补齐后，识别协作伙伴与维护薄弱环节，并另行核对治理角色。','以贡献来源视图组织后续数据补充',3)],bridge='成熟项目形成协作基础，新仓库与新项目则提供观察下一轮技术供给的入口。'),
5:dict(code='E',name='全球新势力开源仓库与项目排行榜',short='新势力',role='新的技术供给从哪里出现',question='新仓库与新项目正在形成怎样的协作起点，哪些技术方向最为集中？',metric='仓库与项目独立排名。新仓库可以属于已有项目；新项目要求纳入仓库均在本期新建。技术领域与创建批次补充结构观察。',window='2025.07—2026.06 · 新仓库 Top 30 / 新项目 Top 30',findings=[('单仓库聚集与多仓库供给并存','openclaw/openclaw 以 7,047.46 居新仓库榜首；新项目榜首 CANN 为 14,719.47，纳入 68 个仓库。两者属于不同统计单元。',1),('两个榜单，呈现不同技术结构','新仓库原表中，AI 基础软件占 18 / 30；按编辑分类，新项目中的 Agent 工具占 25 / 30。仓库供给与项目入口各有侧重。',3),('入榜对象来自不同创建批次','新仓库名单中，2025 年 9 月创建的有 9 个；新项目首仓创建日期在 2025 年 8 月、2026 年 2 月各有 7 个。',3)],guide='先分别阅读仓库榜与项目榜，再展开有证据的关联仓库，最后切换领域与创建批次观察供给结构。',figures=['新仓库榜：单个协作入口如何形成影响','新项目榜：从仓库进入多组件共同成果','技术结构：领域差异与创建批次'],hints=['保留完整仓库路径、平台和创建日期；所属项目可联动查看。','CANN 保留原表 68 个纳入仓库，目前仅连接 8 个已核对的入榜仓库。','创建批次只回溯本期 Top 30 名单；技术分类与语言采用各自口径。'],actions=[('按不同起点支持新势力','对单仓库团队关注协作者加入和维护负担；对多仓库项目关注组件分工、接口稳定与跨仓协作。','对照两类榜单的对象规模与组织方式',1),('建立一致窗口的后续跟踪','按创建后 30、60、90 天持续补充外部贡献、留存与实际复用记录，形成比一次排名更完整的成长观察。','从创建批次安排后续观察窗口',3),('持续维护项目与仓库映射','明确新仓库属于既有项目还是新项目，记录纳入清单、生效时间和分类规则，让新势力定义可以复核。','从关联仓库视图补齐统计映射',2)],bridge='新的开放供给不仅表现为代码项目。模型榜进一步观察模型版本及其复用影响。'),
6:dict(code='M',name='全球开源大模型影响力排行榜',short='模型',role='哪些模型进入复用网络',question='哪些模型版本形成了重要的复用影响，主要任务与发布力量怎样分布？',metric='ModelRank 排列 2026 年 8 月真实 Top 100 模型版本。任务榜描述应用方向，组织榜按发布账户统计版本供给；头部席位和任务覆盖提供补充视角。',window='2026.08 · ModelRank / 模型版本 / 发布账户',findings=[('Qwen 的头部位置覆盖多个版本','Qwen3.8-27B 居首，ModelRank 为 27,930.09。Qwen 账户在 Top 20 中占 16 席，在 Top 100 中占 41 席。',1),('文本生成与图文理解占 79 席','两类任务分别有 52、27 个版本。机器人、语音识别等专门任务也有模型入榜；另有 3 个版本的任务未识别。',2),('集中供给与多类发布力量并存','Qwen 41 席、Google 15 席，meta-llama 与 Unsloth 各 6 席。全榜有 23 个已识别发布账户，另有 1 个版本的账户未识别。',3)],guide='从主榜查具体版本，在任务图寻找同类模型，再到组织榜比较入榜规模、头部位置与任务布局。',figures=['模型榜：具体版本的复用网络影响力','任务结构：数量、构成与供给覆盖','发布组织榜：入榜规模与任务布局'],hints=['参数范围、许可和上游声明在档案中展开，模型卡资料另标核验日期。','每格代表一个模型版本；任务覆盖矩阵可点击查看对应模型。','按发布账户独立计数，组织身份资料补充识别；同一母公司下不同账户不自动合并。'],actions=[('从任务出发建立模型候选集','使用者先按任务筛选，再结合能力测试、许可条款、资源需求与维护信息作选择。','从任务图联动到完整模型榜',2),('降低模型理解与复用的门槛','发布者完善模型卡、适用任务、许可证和明确的上游来源，让使用者能够识别版本差异与复用条件。','从模型档案核对需要补充的信息',1),('用一致粒度比较组织供给','分别观察企业、研究机构、社区和个人账户，结合入榜规模与任务布局寻找互补方向，并持续核验组织映射。','在组织榜选择同类账户进行对照',3)],bridge='从主体榜单进入技术图谱，下一章进一步展开这些项目与模型所在的技术领域。')}

def overview():
    return '<section class="gosr-reading-guide" id="gosr-reading-guide"><span class="gosr-kicker">SIX RANKINGS · ONE READING PATH</span><h3>从协作节点，到共同成果，再到新的开放供给。</h3><p>六个主题依次展开，每节采用同一阅读路径：<b>核心问题 → 指标定位 → 核心发现 → 交互证据 → 行动建议</b>。先读发现，再进入排行榜核对具体对象，最后连接可采取的行动。</p><div class="gosr-topic-chain">'+''.join(f'<a href="#ch03-s0{n}"><b>{v["code"]}-Ranking</b><span>{v["role"]}</span></a>' for n,v in TOPICS.items())+'</div></section>'

def normalize(text,n):
    tree=Tree(text);root=next(x for x in tree.root.walk() if x.attrs.get('id')==f'ch03-s0{n}');q=TOPICS[n];root.add('gosr-reading-section');root.set('aria-labelledby',f'ch03-s0{n}-title')
    figures=[x for x in root.walk() if x.tag=='figure'];methods=[x for x in root.walk() if x.tag=='details' and x.has('cr-method-inline')]
    pref=f'ch03-s0{n}';parts=[]
    parts+=fragment(f'<div class="section-topline"><span>3.{n} / {q["code"]}-RANKING</span><span>{q["short"]}榜单 · 交互评审版 1.3</span></div><h2 id="{pref}-title">3.{n} {q["name"]} <span class="gosr-system-id">({q["code"]}-Ranking)</span></h2>')
    parts+=fragment('<nav class="gosr-reading-path" aria-label="本节五步阅读路径">'+''.join(f'<a href="#{pref}-step-{i}"><b>0{i}</b>{label}</a>' for i,label in enumerate(PATH,1))+'</nav>')
    parts+=fragment(f'<section class="gosr-question-block" id="{pref}-step-1"><span class="gosr-kicker">01 / 核心问题</span><h3>{q["question"]}</h3></section><section class="gosr-metric-block" id="{pref}-step-2"><span class="gosr-kicker">02 / 指标定位</span><p>{q["metric"]}</p><small>{q["window"]}</small></section>')
    parts+=fragment(f'<section class="gosr-findings-block" id="{pref}-step-3"><span class="gosr-kicker">03 / 核心发现</span><div class="gosr-findings-grid">'+''.join(f'<article><h3>{title}</h3><p>{body}</p><a href="#fig-3-{n}-{fig}">查看证据 · 图 3-{n}-{fig} ↓</a></article>' for title,body,fig in q['findings'])+'</div></section>')
    parts+=fragment(f'<div class="gosr-evidence-heading" id="{pref}-step-4"><span class="gosr-kicker">04 / 交互证据</span><p>{q["guide"]}</p></div><nav class="cr-section-nav" aria-label="{q["short"]}图表导航">'+''.join(f'<a href="#fig-3-{n}-{i}"><b>0{i}</b> {label}</a>' for i,label in enumerate(q['figures'],1))+'</nav>')
    for i,fig in enumerate(figures,1):
        aliases=f'<span class="gosr-anchor" id="rr-{n}-supp-{i}"></span>' if i>1 and n!=2 else f'<span class="gosr-anchor" id="{("cr-history" if i==2 else "cr-community")}"></span>' if i>1 else ''
        parts+=fragment(aliases+f'<div class="gosr-figure-heading"><span>图 3-{n}-{i}</span><div><h3>{q["figures"][i-1]}</h3><p>{q["hints"][i-1]}</p></div></div>')
        parts.append(fig)
    parts+=fragment(f'<section class="gosr-actions-block" id="{pref}-step-5"><span class="gosr-kicker">05 / 行动建议</span><h3>把榜单观察，连接到下一步行动。</h3><div class="gosr-action-list">'+''.join(f'<article><span>0{i}</span><div><h4>{title}</h4><p>{body}</p><a href="#fig-3-{n}-{fig}">{link} ↗</a></div></article>' for i,(title,body,link,fig) in enumerate(q['actions'],1))+'</div></section>')
    parts+=methods
    parts+=fragment(f'<p class="gosr-section-bridge">{q["bridge"]}</p>')
    prev=f'#ch03-s0{n-1}' if n>1 else '/2026/zh/chapters/02/'
    nex=f'#ch03-s0{n+1}' if n<6 else '/2026/zh/chapters/04/'
    parts+=fragment(f'<nav class="gosr-section-end" aria-label="章节阅读导航"><a href="{prev}">← {TOPICS[n-1]["code"]+"-Ranking" if n>1 else "第二章 GOSO"}</a><a href="#gosr-reading-guide">本章阅读路径</a><a href="{nex}">{TOPICS[n+1]["code"]+"-Ranking" if n<6 else "第四章 GOSL"} →</a></nav>')
    root.children=parts
    return tree.root.html()
